solution.solution.ts:
type Result<T> = { ok: true; value: T } | { ok: false; error: string };

type Expr =
  | { kind: "num"; value: number }
  | { kind: "var"; name: string }
  | { kind: "unary"; op: "-"; arg: Expr }
  | { kind: "binary"; op: "+" | "-" | "*" | "/" | "^"; left: Expr; right: Expr }
  | { kind: "call"; name: string; args: Expr[] };

type Token =
  | { type: "num"; value: number; pos: number }
  | { type: "name"; value: string; pos: number }
  | { type: "sym"; value: string; pos: number };

class CalcError extends Error {}

const isDigit = (c: string | undefined): boolean => c !== undefined && c >= "0" && c <= "9";
const isNameStart = (c: string | undefined): boolean =>
  c !== undefined && ((c >= "a" && c <= "z") || (c >= "A" && c <= "Z") || c === "_");

function tokenize(source: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;
  while (i < source.length) {
    const c = source[i];
    if (c === " " || c === "\t" || c === "\n" || c === "\r") { i++; continue; }
    if (isDigit(c) || (c === "." && isDigit(source[i + 1]))) {
      const start = i;
      while (isDigit(source[i])) i++;
      if (source[i] === ".") {
        i++;
        while (isDigit(source[i])) i++;
      }
      tokens.push({ type: "num", value: Number(source.slice(start, i)), pos: start });
      continue;
    }
    if (isNameStart(c)) {
      const start = i;
      while (isNameStart(source[i]) || isDigit(source[i])) i++;
      tokens.push({ type: "name", value: source.slice(start, i), pos: start });
      continue;
    }
    if ("+-*/^(),".includes(c)) { tokens.push({ type: "sym", value: c, pos: i }); i++; continue; }
    throw new CalcError(`unexpected "${c}" at ${i}`);
  }
  return tokens;
}

function parseTokens(tokens: Token[]): Expr {
  let p = 0;
  const fail = (t: Token | undefined): never => {
    throw new CalcError(t ? `unexpected "${t.value}" at ${t.pos}` : "unexpected end");
  };
  const isSym = (v: string): boolean => {
    const t = tokens[p];
    return t !== undefined && t.type === "sym" && t.value === v;
  };
  const expect = (v: string): void => {
    if (!isSym(v)) fail(tokens[p]);
    p++;
  };

  function expression(): Expr {
    let left = term();
    while (isSym("+") || isSym("-")) {
      const op = tokens[p++].value as "+" | "-";
      left = { kind: "binary", op, left, right: term() };
    }
    return left;
  }

  function term(): Expr {
    let left = unary();
    while (isSym("*") || isSym("/")) {
      const op = tokens[p++].value as "*" | "/";
      left = { kind: "binary", op, left, right: unary() };
    }
    return left;
  }

  function unary(): Expr {
    if (isSym("-")) {
      p++;
      return { kind: "unary", op: "-", arg: unary() };
    }
    return power();
  }

  function power(): Expr {
    const base = primary();
    if (isSym("^")) {
      p++;
      return { kind: "binary", op: "^", left: base, right: unary() };
    }
    return base;
  }

  function primary(): Expr {
    const t = tokens[p];
    if (t === undefined) return fail(t);
    if (t.type === "num") { p++; return { kind: "num", value: t.value }; }
    if (t.type === "name") {
      p++;
      if (!isSym("(")) return { kind: "var", name: t.value };
      p++;
      const args: Expr[] = [];
      if (!isSym(")")) {
        args.push(expression());
        while (isSym(",")) { p++; args.push(expression()); }
      }
      expect(")");
      return { kind: "call", name: t.value, args };
    }
    if (t.value === "(") {
      p++;
      const inner = expression();
      expect(")");
      return inner;
    }
    return fail(t);
  }

  const tree = expression();
  if (p < tokens.length) fail(tokens[p]);
  return tree;
}

interface Fn { min: number; max: number; run: (...xs: number[]) => number }

const FUNCTIONS: Record<string, Fn> = {
  abs: { min: 1, max: 1, run: Math.abs },
  sqrt: {
    min: 1, max: 1,
    run: x => { if (x < 0) throw new CalcError("sqrt of a negative number"); return Math.sqrt(x); },
  },
  min: { min: 1, max: Infinity, run: Math.min },
  max: { min: 1, max: Infinity, run: Math.max },
};

function evalExpr(e: Expr, vars: Record<string, number>): number {
  switch (e.kind) {
    case "num":
      return e.value;
    case "var":
      if (!Object.hasOwn(vars, e.name)) throw new CalcError(`unknown variable ${e.name}`);
      return vars[e.name];
    case "unary":
      return -evalExpr(e.arg, vars);
    case "binary": {
      const a = evalExpr(e.left, vars);
      const b = evalExpr(e.right, vars);
      switch (e.op) {
        case "+": return a + b;
        case "-": return a - b;
        case "*": return a * b;
        case "/":
          if (b === 0) throw new CalcError("division by zero");
          return a / b;
        case "^": return a ** b;
      }
      throw new CalcError("unknown operator");
    }
    case "call": {
      const f = Object.hasOwn(FUNCTIONS, e.name) ? FUNCTIONS[e.name] : undefined;
      if (!f) throw new CalcError(`unknown function ${e.name}`);
      if (e.args.length < f.min || e.args.length > f.max) {
        throw new CalcError(f.min === f.max ? `${e.name} takes ${f.min} argument` : `${e.name} needs at least ${f.min} argument`);
      }
      return f.run(...e.args.map(arg => evalExpr(arg, vars)));
    }
    default: {
      const unreachable: never = e;
      throw new CalcError(`unknown node ${JSON.stringify(unreachable)}`);
    }
  }
}

function attempt<T>(work: () => T): Result<T> {
  try {
    return { ok: true, value: work() };
  } catch (err) {
    if (err instanceof CalcError) return { ok: false, error: err.message };
    throw err;
  }
}

function parse(source: string): Result<Expr> {
  return attempt(() => parseTokens(tokenize(source)));
}

function evaluate(source: string, vars: Record<string, number> = {}): Result<number> {
  return attempt(() => evalExpr(parseTokens(tokenize(source)), vars));
}

unitTests:
const value = (src: string, vars: Record<string, number> = {}) => {
  const r = evaluate(src, vars);
  return r.ok ? r.value : `error: ${r.error}`;
};

test("arithmetic and precedence", () => {
  checkEq(value("1 + 2 * 3"), 7);
  checkEq(value("(1 + 2) * 3"), 9);
  checkEq(value("8 - 3 - 2"), 3);
  checkEq(value("10 / 4"), 2.5);
  checkEq(value("1.5 + .5 + 3."), 5);
});

test("powers and unary minus", () => {
  checkEq(value("2 ^ 3 ^ 2"), 512);
  checkEq(value("-2 ^ 2"), -4);
  checkEq(value("2 ^ -1"), 0.5);
  checkEq(value("--3"), 3);
  checkEq(value("-(1 + 2) * 2"), -6);
});

test("variables", () => {
  checkEq(value("x * x + y", { x: 3, y: 1 }), 10);
  checkEq(value("_tmp2 + 1", { _tmp2: 4 }), 5);
  checkEq(value("rate * 2"), "error: unknown variable rate");
  checkEq(value("toString"), "error: unknown variable toString");
});

test("functions", () => {
  checkEq(value("max(1, 7, 3) + min(4)"), 11);
  checkEq(value("sqrt(16) + abs(-2)"), 6);
  checkEq(value("max(2, a) * 2", { a: 5 }), 10);
  checkEq(value("abs()"), "error: abs takes 1 argument");
  checkEq(value("sqrt(1, 2)"), "error: sqrt takes 1 argument");
  checkEq(value("min()"), "error: min needs at least 1 argument");
  checkEq(value("foo(1)"), "error: unknown function foo");
  checkEq(value("sqrt(-1)"), "error: sqrt of a negative number");
});

test("syntax errors", () => {
  checkEq(value("1 +"), "error: unexpected end");
  checkEq(value(""), "error: unexpected end");
  checkEq(value("(1 + 2"), "error: unexpected end");
  checkEq(value("1 + * 2"), 'error: unexpected "*" at 4');
  checkEq(value("2 $ 3"), 'error: unexpected "$" at 2');
  checkEq(value("1 2"), 'error: unexpected "2" at 2');
  checkEq(value("max(1,)"), 'error: unexpected ")" at 6');
  checkEq(value("4 / (2 - 2)"), "error: division by zero");
});

test("syntax trees", () => {
  checkEq(parse("1 + x"), {
    ok: true,
    value: { kind: "binary", op: "+", left: { kind: "num", value: 1 }, right: { kind: "var", name: "x" } },
  });
  checkEq(parse("-f(2)"), {
    ok: true,
    value: { kind: "unary", op: "-", arg: { kind: "call", name: "f", args: [{ kind: "num", value: 2 }] } },
  });
  checkEq(parse("g()"), { ok: true, value: { kind: "call", name: "g", args: [] } });
  checkEq(parse("1 +"), { ok: false, error: "unexpected end" });
});

